def most_common_word(text: str) -> str:
    counts = {}
    for w in text.lower().split():
        counts[w] = counts.get(w, 0) + 1
    best = ''
    best_n = 0
    for w in counts:
        if counts[w] > best_n:
            best, best_n = w, counts[w]
    return best

